const STAGE = {
  ideia: 'Ideia',
  backlog: 'Backlog',
  priorizacao: 'Priorização',
  em_desenvolvimento: 'Em Desenvolvimento',
  em_teste: 'Em Teste',
  concluido: 'Concluído',
  showcase: 'Showcase',
  cancelado: 'Cancelado',
};

function brl(n) {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(Number(n) || 0);
}
function horas(n) {
  return new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 1 }).format(Number(n) || 0) + ' h';
}
function dataCurta(iso) {
  if (!iso) return '—';
  return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeZone: 'America/Sao_Paulo' }).format(new Date(iso));
}
function plural(n, um, muitos) {
  const v = Number(n) || 0;
  return v + ' ' + (v === 1 ? um : muitos);
}
function linha(item, quando) {
  const ganho = item.hours_saved_month == null ? 'horas não informadas' : horas(item.hours_saved_month) + '/mês';
  const valor = item.cost_saved_month == null ? 'valor não informado' : brl(item.cost_saved_month) + '/mês';
  const area = item.area_name ? ' · ' + item.area_name : '';
  return '- ' + item.title + ' — ' + (STAGE[item.stage] || item.stage) + area + ' — ' + item.owner_name + ' — ' + ganho + ' — ' + valor + ' — ' + quando;
}
function bloco(titulo, itens, vazio, quando) {
  const lista = Array.isArray(itens) ? itens : [];
  if (!lista.length) return titulo + '\n' + vazio;
  return [titulo].concat(lista.map((item) => linha(item, quando(item)))).join('\n');
}
function texto(rel) {
  const m = rel.metricas || {};
  const g = rel.ganhos || {};
  const v = rel.valor || {};
  const linhas = [];
  if (rel.diretor_nome) linhas.push('Olá, ' + rel.diretor_nome);
  linhas.push(
    'Relatório mensal — ' + rel.nome,
    rel.diretor_nome ? 'Diretor: ' + rel.diretor_nome : null,
    'Período: ' + rel.rotulo,
    '',
    'Métricas',
    '- ' + plural(m.iniciativas, 'iniciativa no portfólio', 'iniciativas no portfólio') + ' (' + plural(m.ativas, 'ativa', 'ativas') + ', ' + plural(m.concluidas, 'concluída', 'concluídas') + ', ' + plural(m.canceladas, 'cancelada', 'canceladas') + ')',
    '- ' + plural(m.criadas_no_mes, 'criada no mês', 'criadas no mês'),
    '- ' + plural(m.atualizadas_no_mes, 'atualizada no mês', 'atualizadas no mês'),
    '- ' + plural(m.concluidas_no_mes, 'concluída no mês', 'concluídas no mês'),
    '- ' + plural(m.em_alerta, 'em alerta', 'em alerta') + ' (sem atualização há mais de 14 dias)',
    '- ' + plural(m.com_ia, 'com uso de IA', 'com uso de IA'),
    '',
    'Ganhos',
    '- ' + horas(g.horas_devolvidas_mes) + '/mês devolvidas (iniciativas concluídas)',
    '- ' + horas(g.horas_concluidas_no_mes) + '/mês nas concluídas deste mês',
    '- ' + horas(g.horas_criadas) + '/mês nas iniciativas criadas no mês',
    '- ' + horas(g.horas_atualizadas) + '/mês nas iniciativas atualizadas no mês',
    '- ' + horas(g.horas_portfolio) + '/mês no portfólio inteiro da área',
    '- ' + (Number(m.com_horas) || 0) + ' de ' + (Number(m.iniciativas) || 0) + ' com horas informadas',
    '',
    'Valor para a área',
    '- ' + brl(v.mensal_realizado) + '/mês realizados · ' + brl(v.anual_realizado) + '/ano',
    '- ' + brl(v.mensal_concluidas_no_mes) + '/mês nas concluídas deste mês',
    '- ' + brl(v.mensal_movimento) + '/mês associados ao movimento (' + brl(v.mensal_criadas) + ' nas criadas, ' + brl(v.mensal_atualizadas) + ' nas atualizadas)',
    '- ' + (Number(m.com_valor) || 0) + ' de ' + (Number(m.iniciativas) || 0) + ' com valor em R$ informado',
    '',
    bloco('Iniciativas criadas no mês', rel.criadas, 'Nenhuma iniciativa criada neste mês.', (item) => 'criada em ' + dataCurta(item.created_at)),
    '',
    bloco('Iniciativas atualizadas no mês', rel.atualizadas, 'Nenhuma iniciativa atualizada neste mês.', (item) => 'atualizada em ' + dataCurta(item.last_activity_at)),
    '',
    'Criadas no mês não se repetem em atualizadas. A carga legada não entra como criação.',
  );
  let site = '';
  try { site = String($env.PULSO_SITE_URL || '').replace(/\/$/, ''); } catch (erro) { site = ''; }
  if (site) linhas.push('', 'Painel: ' + site + '/dashboard');
  return linhas.filter((linha) => linha != null).join('\n');
}

const linhas = [];
for (const item of $input.all()) {
  const corpo = item.json;
  if (Array.isArray(corpo)) linhas.push(...corpo);
  else if (corpo && Array.isArray(corpo.data)) linhas.push(...corpo.data);
  else if (corpo && corpo.slug) linhas.push(corpo);
  else if (corpo && corpo.message && !corpo.slug) throw new Error(corpo.message);
}
return linhas.map((rel) => ({
  json: {
    ...rel,
    assunto: 'Pulso — ' + rel.nome + ' — ' + rel.rotulo,
    texto: texto(rel),
  },
}));
